@block BadUnits begin
    @parameters begin
        tau::Real = 1.0, [unit = "N*m", description = "Torque parameter"]
        F::Real = 1.0, [unit = "N", description = "Force parameter"]
    end
    @variables P::Real = 0.0, [state = :prefer]
    @equations begin
        ddt(P) ~ tau + F
    end
end
